definition.script:
pipeline {
    agent {label 'Agent1'}

    stages {
        stage('Build') {
            steps {
                // Get some code from a GitHub repository
                git branch: 'tp02', url: 'https://github.com/SorThanaroth/DevOps.git'

                // Copy nev, run composer...
                sh 'cp .env.example .env && composer install && npm i && php artisan key:generate'
            }

        }
        stage('Test'){
            steps {
                sh 'php artisan test'
            }
        }
    }
}
